package template

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ScanDir is where a template is written to be scanned: one fixed directory per
// slug under ~/.devdesk/cache/template-scan.
//
// Fixed rather than temporary because the scan is cached by path — the result
// shows up in `:sec` under the directory it was made from, and a fresh temp
// directory each time would leave a dead entry behind for every scan.
func ScanDir(slug string) (string, error) {
	if !slugPattern.MatchString(slug) {
		return "", fmt.Errorf("slug %q must be lowercase letters, digits and dashes", slug)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".devdesk", "cache", "template-scan", slug), nil
}

// Materialize writes a template's files to its ScanDir, replacing whatever a
// previous scan left there, and returns the directory.
//
// Only that directory is ever removed: it is computed here from a validated
// slug, never passed in, so nothing a caller does can point the removal
// elsewhere. A file whose path would land outside it is refused — the readers
// already refuse those, and this is the second lock on the door that matters
// most, the one that writes to disk.
func Materialize(slug string, files []File) (string, error) {
	dir, err := ScanDir(slug)
	if err != nil {
		return "", err
	}
	if err := os.RemoveAll(dir); err != nil {
		return "", err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", err
	}

	for _, f := range files {
		target := filepath.Join(dir, filepath.FromSlash(f.Path))
		if rel, err := filepath.Rel(dir, target); err != nil || rel == "." || strings.HasPrefix(rel, "..") {
			return "", fmt.Errorf("template file %q would be written outside its directory", f.Path)
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o700); err != nil {
			return "", err
		}
		mode := os.FileMode(0o600)
		if f.Executable {
			mode = 0o700
		}
		if err := os.WriteFile(target, f.Content, mode); err != nil {
			return "", err
		}
	}
	return dir, nil
}
package templates

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/template"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/viewer"
)

// previewTimeout bounds a preview: a fetch that cannot finish should say so
// rather than leave the viewer waiting.
const previewTimeout = 2 * time.Minute

// previewSource lists the files a template would put in a new repository. It is
// a viewer.Source, so the read happens in the viewer's own Init and one place
// reports what went wrong (see viewer.OpenRequestMsg).
type previewSource struct {
	entry template.Entry
	creds template.Credentials
}

func (s previewSource) Name() string { return s.entry.Name + " — files" }

// Kind is plain: the listing is text with no structure worth deriving a view of.
func (s previewSource) Kind() viewer.Kind { return viewer.KindPlain }

func (s previewSource) Load() ([]byte, error) {
	ctx, cancel := context.WithTimeout(context.Background(), previewTimeout)
	defer cancel()

	files, err := template.Fetch(ctx, s.entry.Source, s.creds)
	if err != nil {
		return nil, err
	}
	return []byte(listing(s.entry, files)), nil
}

// listing formats what was fetched: a summary line, where it came from, then
// one line per file with its size and an `x` for the execute bit.
func listing(entry template.Entry, files []template.File) string {
	sorted := append([]template.File(nil), files...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Path < sorted[j].Path })

	total := 0
	for _, f := range sorted {
		total += len(f.Content)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "%s — %s, %s\n", entry.Name, sharedcomponents.Plural(len(sorted), "file", "files"), template.FormatSize(total))
	fmt.Fprintf(&b, "%s\n\n", sourceSummary(entry.Source)+refSuffix(entry.Source))

	if len(sorted) == 0 {
		b.WriteString("This template has no files: a repository made from it would be empty.\n")
		return b.String()
	}
	for _, f := range sorted {
		mode := "-"
		if f.Executable {
			mode = "x"
		}
		fmt.Fprintf(&b, "%s  %9s  %s\n", mode, template.FormatSize(len(f.Content)), f.Path)
	}
	return b.String()
}

func refSuffix(s template.Source) string {
	if s.Ref == "" {
		return ""
	}
	return " @ " + s.Ref
}
