// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		return m.handleWindowSize(msg)

	case CatalogLoadedMsg:
		return m.handleCatalogLoaded(msg)

	case SavedMsg:
		return m.handleSaved(msg)

	case DeletedMsg:
		return m.handleDeleted(msg)

	case DepsCheckedMsg:
		m.deps = &msg.Deps
		return m, nil

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case ScanCompleteMsg:
		return m.handleScanComplete(msg)

	case FormSubmitMsg:
		return m.handleFormSubmit(msg)

	case FormCancelMsg:
		m.form = nil
		return m, nil

	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleConfirmDelete()

	case sharedcomponents.ConfirmModalNoMsg:
		m.confirmModal = nil
		m.pendingDelete = ""
		return m, nil

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

